#!/usr/bin/env python3

def interpret_cow(program):
    # Remove any characters that aren't part of the COW language
    program = ''.join(c for c in program if c in "MOomoo")

    # Initialize memory and pointers
    memory = [0]
    memory_pointer = 0
    instruction_pointer = 0
    register = 0
    output = ""

    # Parse commands
    commands = []
    i = 0
    while i < len(program):
        # Check for MOO variants
        if i + 2 < len(program) and program[i:i+3].lower() == 'moo':
            commands.append(program[i:i+3])
            i += 3
        else:
            i += 1

    # Execute commands
    i = 0
    while i < len(commands):
        cmd = commands[i]

        # MOO: moo is executed as a label.
        if cmd == 'moo':
            i += 1
            continue

        # MOo: Moves memory pointer to next block
        elif cmd == 'MOo':
            memory_pointer += 1
            if memory_pointer >= len(memory):
                memory.append(0)
            i += 1

        # MoO: Moves memory pointer to previous block
        elif cmd == 'MoO':
            memory_pointer = max(0, memory_pointer - 1)
            i += 1

        # mOo: Moves memory pointer to the block with the same value as current.
        elif cmd == 'mOo':
            current_value = memory[memory_pointer]
            found = False
            for j in range(len(memory)):
                if j != memory_pointer and memory[j] == current_value:
                    memory_pointer = j
                    found = True
                    break
            if not found:
                pass  # If no matching block exists, do nothing
            i += 1

        # MOO: If current memory block has a 0, execute next command, or else skip.
        elif cmd == 'MOO':
            if memory[memory_pointer] == 0:
                i += 1
            else:
                i += 2

        # Moo: If current memory block is not 0, jump back to command after last moo command.
        elif cmd == 'Moo':
            if memory[memory_pointer] != 0:
                for j in range(i-1, -1, -1):
                    if commands[j] == 'moo':
                        i = j + 1
                        break
                else:
                    i += 1  # No 'moo' found
            else:
                i += 1

        # OOO: Sets current memory block to 0
        elif cmd == 'OOO':
            memory[memory_pointer] = 0
            i += 1

        # MMM: If register is 0, asks for input and stores ASCII in the register, else copies register to current memory.
        elif cmd == 'MMM':
            if register == 0:
                # For our purposes, we'll just leave this as 0 since we don't have interactive input
                pass
            else:
                memory[memory_pointer] = register
            i += 1

        # OOM: Prints value of current memory block as an ASCII character
        elif cmd == 'OOM':
            output += chr(memory[memory_pointer])
            i += 1

        # oom: Prints value of current memory block as a number
        elif cmd == 'oom':
            output += str(memory[memory_pointer])
            i += 1

        # ooM: Read a number from input and put it in current memory
        elif cmd == 'ooM':
            # For our purposes, we'll just leave this as 0 since we don't have interactive input
            i += 1

        # moO: Increment current memory block by 1. (255+1=0)
        elif cmd == 'moO':
            memory[memory_pointer] = (memory[memory_pointer] + 1) % 256
            i += 1

        # mOO: Decrement current memory block by 1. (0-1=255)
        elif cmd == 'mOO':
            memory[memory_pointer] = (memory[memory_pointer] - 1) % 256
            i += 1

        # MoO: Copy value of current memory block to register.
        elif cmd == 'MoO':
            register = memory[memory_pointer]
            i += 1

        # MOo: Copy value from register to current memory block.
        elif cmd == 'MOo':
            memory[memory_pointer] = register
            i += 1

        # Invalid command
        else:
            i += 1

    return output

